response:
**Gates before launch.** I run four gates in order and stop if any of them fails. Gate 1: `git diff --quiet HEAD -- spe/predictions/r04.yaml spe/plans/r04.md` must come back clean, so the prediction is frozen. Gate 2 is the grader selftest. `spe/evals/graders/grade.py` must pass the oracle on all 50 tickets. The oracle uses labels copied from `spe/evals/tasks/answers.json`. The grader must fail an empty `output.json` and a wrong label on both checks. Gate 3 is the control. I regrade round 3's saved outputs with today's grader. Category and priority accuracy must match the r03 rows in `spe/prediction-log.md`. A mismatch means the grader changed, and I halt. Gate 4 is the dry run. I launch the script with `{dryRun: true}` on 3 cells: B/T01, C2/T01, and C2/T02, which is 15 trials. Every trial must return output that matches the schema, get a grade row and a tone score, and have zero peek hits. From the dry run I read the cost per trial and per agent, and I put those numbers in `args.est`. Then I check that 100 cells at that cost fit under $40 with the $3 tail held back. After that I commit the script locally as `SPE r04 evaluate (harness)`, with no push, and launch the full run with `{est: {...}}`. The script repeats gates 1 to 3 itself and refuses a full run without `args.est`.

Defaults I chose:
- I assumed round 3's runner contract carries over. `node spe/evals/harness/run-trial.js --round --config --ticket --trial --out` writes `output.json` and `transcript.jsonl` and prints `sut_cost_usd`.
- Tickets are T01 to T50. You can override the runner and the ticket list in args.
- `grade.py` takes `--answers --ticket --runs --json`.
- The $40 cap counts the API cost the runner reports plus the agent cost estimates from `args.est`.
- Split cells get 3 extra trials each, with 60 extra trials at most. Extra trials are reported separately. The headline numbers use trials 1 to 5 only, so they line up with `spe/predictions/r04.yaml`.

```js
export const meta = {
  name: 'spe-round-eval',
  description: 'SPE evaluate step. Configs B and C2 on 50 tickets with 5 trials per cell. A code grader checks label.category and label.priority. An Opus judge scores reply tone. Spend is capped.',
  phases: ['Gates', 'Trials', 'Peek scan', 'Split cells', 'Failure analysis', 'Completeness critic'],
};

// ROUND is the only place the round number is written.
const ROUND = 4;
const pad2 = (n) => String(n).padStart(2, '0');
const RR = `r${pad2(ROUND)}`;
const PREV = `r${pad2(ROUND - 1)}`;

const A = typeof args === 'object' && args !== null ? args : {};
const DRY = A.dryRun === true;
const MODEL = 'opus';

const CONFIGS = ['B', 'C2'];
const TICKETS = A.tickets ?? Array.from({ length: 50 }, (_, i) => `T${pad2(i + 1)}`);
const TRIALS = 5;
const MAIN_TRIALS = Array.from({ length: TRIALS }, (_, i) => i + 1);
const EXTRA_PER_SPLIT = DRY ? 0 : (A.extraPerSplit ?? 3);
const EXTRA_MAX = DRY ? 0 : (A.extraMax ?? 60);
const DRY_CELLS = A.dryCells ?? [
  { config: 'B', ticket: TICKETS[0] },
  { config: 'C2', ticket: TICKETS[0] },
  { config: 'C2', ticket: TICKETS[1] },
];

const CAP_USD = A.capUsd ?? 40;
const TAIL_USD = A.tailUsd ?? 3; // Held back for the peek scans, failure analysis, and critic.
const GRADER_FAIL_MAX = A.graderFailMax ?? 3;

const RUNNER = A.runner ?? 'node spe/evals/harness/run-trial.js';
const RUN_DIR = `spe/evals/runs/${RR}`;
const PREV_RUN_DIR = `spe/evals/runs/${PREV}`;
const GRADER = 'spe/evals/graders/grade.py';
const ANSWERS = 'spe/evals/tasks/answers.json';
const JUDGE_RUBRIC = 'spe/evals/graders/judge.md';

const OFF_LIMITS = ['spe/evals/graders/', ANSWERS, 'spe/predictions/', 'spe/plans/', 'spe/prediction-log.md', 'spe/failures.md'];
const OFF_LIMITS_RX = /spe\/evals\/graders\/|answers\.json|spe\/predictions\/|spe\/plans\/|prediction-log\.md|failures\.md/;
const GREP_PATTERN = 'answers\\.json|evals/graders|spe/predictions|spe/plans|prediction-log|failures\\.md';
const HIT_PATH_RX = new RegExp(`${RR}/(${CONFIGS.join('|')})/([^/]+)/t(\\d+)/`);

// Cost estimates. A full run must pass args.est measured in the dry run.
const DRY_EST = { agentUsd: 0.4, trialUsd: 0.1, gradeUsd: 0.3, judgeUsd: 0.5, gateUsd: 0.5, scanUsd: 0.3, analysisUsd: 1.0, criticUsd: 0.5 };
const EST = A.est ? { ...DRY_EST, ...A.est } : (DRY ? DRY_EST : null);

// ---------- Budget ledger ----------
const ledger = { spent: 0, reserved: 0, skips: [] };
const tail = { left: TAIL_USD };
let halt = null;
let graderFailures = 0;
let answerLeak = false;
const money = (x) => `$${x.toFixed(2)}`;
const round2 = (x) => Math.round(x * 100) / 100;
const round3 = (x) => Math.round(x * 1000) / 1000;

function reserve(usd, what) {
  if (halt) {
    ledger.skips.push({ what, reason: `halt: ${halt}` });
    log(`SKIP ${what}. The round is halted: ${halt}.`);
    return false;
  }
  if (ledger.spent + ledger.reserved + usd > CAP_USD) {
    ledger.skips.push({ what, reason: 'cap', usd });
    log(`SKIP ${what}. It would cross the ${money(CAP_USD)} cap. Spent ${money(ledger.spent)}, reserved ${money(ledger.reserved)}.`);
    return false;
  }
  ledger.reserved += usd;
  return true;
}
function settle(reservedUsd, actualUsd) {
  ledger.reserved -= reservedUsd;
  ledger.spent += actualUsd;
}
function useTail(usd, what) {
  if (tail.left < usd) {
    ledger.skips.push({ what, reason: 'tail budget', usd });
    log(`SKIP ${what}. Tail budget left is ${money(tail.left)}.`);
    return false;
  }
  tail.left -= usd;
  ledger.reserved -= usd;
  ledger.spent += usd;
  return true;
}

// ---------- Schemas ----------
const RUN_SCHEMA = {
  type: 'object',
  required: ['trials', 'files_read'],
  properties: {
    trials: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial', 'ok'],
        properties: {
          trial: { type: 'integer' },
          ok: { type: 'boolean' },
          error: { type: 'string' },
          out_dir: { type: 'string' },
          sut_cost_usd: { type: 'number' },
          category: { type: ['string', 'null'] },
          priority: { type: ['string', 'null'] },
          reply: { type: ['string', 'null'] },
          tool_calls: { type: 'integer' },
        },
      },
    },
    files_read: { type: 'array', items: { type: 'string' } },
  },
};
const GRADE_SCHEMA = {
  type: 'object',
  required: ['exit_code', 'trials'],
  properties: {
    exit_code: { type: 'integer' },
    stderr_tail: { type: 'string' },
    trials: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial', 'gradeable'],
        properties: {
          trial: { type: 'integer' },
          gradeable: { type: 'boolean' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
          expected_category: { type: 'string' },
          expected_priority: { type: 'string' },
          reason: { type: 'string' },
        },
      },
    },
  },
};
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'tone_pass', 'reason'],
        properties: { id: { type: 'string' }, tone_pass: { type: 'boolean' }, score: { type: ['number', 'null'] }, reason: { type: 'string' } },
      },
    },
  },
};
const SCAN_SCHEMA = {
  type: 'object',
  required: ['files_scanned', 'hits'],
  properties: {
    files_scanned: { type: 'integer' },
    hits: {
      type: 'array',
      items: { type: 'object', required: ['path', 'match'], properties: { path: { type: 'string' }, line: { type: 'integer' }, match: { type: 'string' } } },
    },
  },
};
const GATE_SCHEMA = {
  type: 'object',
  required: ['predictions_committed', 'selftest_oracle_pass', 'selftest_empty_fails', 'selftest_wrong_fails', 'control_matches', 'detail'],
  properties: {
    predictions_committed: { type: 'boolean' },
    selftest_oracle_pass: { type: 'boolean' },
    selftest_empty_fails: { type: 'boolean' },
    selftest_wrong_fails: { type: 'boolean' },
    control_matches: { type: 'boolean' },
    detail: { type: 'string' },
  },
};
const FA_SCHEMA = {
  type: 'object',
  required: ['types'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'what', 'how_to_spot', 'seen_in', 'count', 'fix'],
        properties: {
          name: { type: 'string' },
          existing_f: { type: ['string', 'null'] },
          kind: { type: 'string' },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          seen_in: { type: 'array', items: { type: 'string' } },
          count: { type: 'integer' },
          fix: { type: 'string' },
        },
      },
    },
  },
};
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'object', required: ['what', 'severity'], properties: { what: { type: 'string' }, severity: { type: 'string' }, evidence: { type: 'string' } } } },
  },
};

// ---------- Prompts ----------
function runPrompt(cell, nums) {
  const cmds = nums
    .map((k) => `${RUNNER} --round ${ROUND} --config ${cell.config} --ticket ${cell.ticket} --trial ${k} --out ${RUN_DIR}/${cell.config}/${cell.ticket}/t${k}`)
    .join('\n');
  return [
    'You operate the eval harness for one cell. You do not grade anything.',
    `Config: ${cell.config}. Ticket: ${cell.ticket}.`,
    'Run these commands one at a time from the repo root:',
    cmds,
    'Each command writes output.json and transcript.jsonl into its --out directory. It prints one JSON line that includes sut_cost_usd.',
    'For each trial, report ok, out_dir, sut_cost_usd, tool_calls, and the label.category, label.priority, and reply fields from output.json. Copy the values exactly.',
    'If a command fails, run it once more. If it fails again, report ok=false and the last error line.',
    'Rules:',
    `- Do not open, list, search, or print anything under these paths: ${OFF_LIMITS.join(', ')}.`,
    '- Do not edit the runner, the prompts, the tool definitions, or any file outside the --out directories.',
    '- Do not judge whether a label is right.',
    'In files_read, list every file you opened or printed.',
  ].join('\n');
}

function gradePrompt(cell, runs) {
  const dirs = runs.map((r) => `${RUN_DIR}/${cell.config}/${cell.ticket}/t${r.trial}`).join(' ');
  return [
    'Run the code grader for one cell and report its output. Do not grade by eye.',
    `Command: python3 ${GRADER} --answers ${ANSWERS} --ticket ${cell.ticket} --runs ${dirs} --json`,
    `The grader checks label.category and label.priority in each output.json against ${ANSWERS}.`,
    'Report exit_code. For each trial (the tN in the directory name), report gradeable, category_ok, priority_ok, and the expected values the grader prints.',
    'If the grader cannot grade a trial, set gradeable=false and copy its reason.',
    'If exit_code is not 0, put the last 20 lines of stderr in stderr_tail.',
    'Do not edit the grader, the answers, or any output.',
  ].join('\n');
}

function judgePrompt(cell, items) {
  return [
    `You are the tone judge. Read ${JUDGE_RUBRIC} and apply it exactly as written.`,
    'Score reply tone only. Ignore whether the category or priority is right.',
    `Every reply below answers support ticket ${cell.ticket}. If the rubric needs the ticket text, read only the ticket file the rubric names. Do not open ${ANSWERS}.`,
    'Score each reply on its own. Do not compare the replies to each other.',
    ...items.map((it) => `--- ${it.id} ---\n${it.reply}`),
    'Return one score per reply id. Give tone_pass, the rubric score, and a one-sentence reason.',
  ].join('\n\n');
}

// ---------- Cell stages ----------
const key = (c) => `${c.config}/${c.ticket}`;

async function runCell(cell, nums, ph) {
  const want = EST.agentUsd + nums.length * EST.trialUsd;
  const what = `run ${key(cell)} trials ${nums.join(',')}`;
  if (!reserve(want, what)) return { ...cell, runs: nums.map((t) => ({ trial: t, skipped: true })) };
  let res = null;
  try {
    res = await agent(runPrompt(cell, nums), { label: `${RR} run ${key(cell)}`, phase: ph, schema: RUN_SCHEMA, model: MODEL });
  } catch (e) {
    settle(want, want);
    log(`Run agent failed for ${key(cell)}: ${e}`);
    return { ...cell, runs: nums.map((t) => ({ trial: t, ok: false, error: `agent failed: ${e}` })) };
  }
  const sut = res.trials.reduce((s, t) => s + (typeof t.sut_cost_usd === 'number' ? t.sut_cost_usd : EST.trialUsd), 0);
  settle(want, EST.agentUsd + sut);
  const badReads = (res.files_read ?? []).filter((p) => OFF_LIMITS_RX.test(p));
  if (badReads.length) log(`PEEK ${key(cell)}: the operator read ${badReads.join(', ')}. Its trials will be voided.`);
  const runs = nums.map((t) => {
    const r = res.trials.find((x) => x.trial === t);
    if (!r) return { trial: t, ok: false, error: 'missing from agent result' };
    return { ...r, peek: badReads.length ? badReads : null };
  });
  return { ...cell, runs };
}

async function gradeCell(c, ph) {
  const todo = c.runs.filter((r) => r.ok && !r.grade);
  if (!todo.length) return c;
  if (!reserve(EST.gradeUsd, `grade ${key(c)}`)) return c;
  let g = null;
  try {
    g = await agent(gradePrompt(c, todo), { label: `${RR} grade ${key(c)}`, phase: ph, schema: GRADE_SCHEMA, model: MODEL });
  } catch (e) {
    log(`Grade agent failed for ${key(c)}: ${e}`);
  }
  settle(EST.gradeUsd, EST.gradeUsd);
  const broken = !g || g.exit_code !== 0 || todo.some((r) => !(g.trials ?? []).find((t) => t.trial === r.trial && t.gradeable));
  if (broken) {
    graderFailures += 1;
    log(`GRADER problem on ${key(c)} (${graderFailures}/${GRADER_FAIL_MAX}). ${g?.stderr_tail ?? ''}`);
    if (graderFailures >= GRADER_FAIL_MAX && !halt) {
      halt = 'broken-grader';
      log('HALT: the grader failed on too many cells. Remaining work is skipped.');
    }
  }
  const byTrial = new Map((g?.trials ?? []).map((t) => [t.trial, t]));
  return { ...c, runs: c.runs.map((r) => (byTrial.has(r.trial) && !r.grade ? { ...r, grade: byTrial.get(r.trial) } : r)) };
}

async function judgeCell(c, ph) {
  const runs = c.runs.map((r) =>
    r.ok && !r.tone && !(typeof r.reply === 'string' && r.reply.trim()) ? { ...r, tone: { tone_pass: false, score: null, reason: 'empty reply' } } : r,
  );
  const todo = runs.filter((r) => r.ok && !r.tone);
  if (!todo.length) return { ...c, runs };
  if (!reserve(EST.judgeUsd, `judge ${key(c)}`)) return { ...c, runs };
  const items = todo.map((r, i) => ({ id: `R${i + 1}`, trial: r.trial, reply: r.reply }));
  let j = null;
  try {
    // The label carries no config name, so the judge stays blind to the config.
    j = await agent(judgePrompt(c, items), { label: `${RR} judge ${c.ticket} cell ${c.idx}`, phase: ph, schema: JUDGE_SCHEMA, model: MODEL });
  } catch (e) {
    log(`Judge agent failed for ${key(c)}: ${e}`);
  }
  settle(EST.judgeUsd, EST.judgeUsd);
  const byTrial = new Map(items.map((it) => [it.trial, (j?.scores ?? []).find((s) => s.id === it.id) ?? null]));
  return { ...c, runs: runs.map((r) => (byTrial.get(r.trial) ? { ...r, tone: byTrial.get(r.trial) } : r)) };
}

// ---------- Peek scan ----------
async function peekScan(ph, byKey) {
  for (const c of byKey.values()) {
    for (const r of c.runs) {
      if (r.peek && !r.voided) r.voided = `operator read ${r.peek.join(', ')}`;
      if (r.peek && r.peek.some((p) => /answers\.json/.test(p))) answerLeak = true;
    }
  }
  if (!useTail(EST.scanUsd, `peek scan (${ph})`)) return { scanned: false };
  let s = null;
  try {
    s = await agent(
      [
        'Scan the trial transcripts for reads of off-limits files. Do not open the off-limits files yourself.',
        `Run: grep -rnE '${GREP_PATTERN}' ${RUN_DIR} --include=transcript.jsonl`,
        `Count the transcripts: find ${RUN_DIR} -name transcript.jsonl | wc -l`,
        'Report every hit with its path, line number, and the matched text (up to 200 characters). Do not filter hits. Report files_scanned.',
      ].join('\n'),
      { label: `${RR} peek scan (${ph})`, phase: 'Peek scan', schema: SCAN_SCHEMA, model: MODEL },
    );
  } catch (e) {
    log(`Peek scan failed: ${e}. Treat this round as unscanned.`);
    return { scanned: false };
  }
  let voided = 0;
  for (const h of s.hits) {
    const m = h.path.match(HIT_PATH_RX);
    if (!m) continue;
    const c = byKey.get(`${m[1]}/${m[2]}`);
    const r = c?.runs.find((x) => x.trial === Number(m[3]));
    if (r && !r.voided) {
      r.voided = `transcript hit: ${h.match.slice(0, 120)}`;
      voided += 1;
    }
    if (/answers\.json/.test(h.match)) answerLeak = true;
  }
  log(`Peek scan (${ph}): ${s.files_scanned} transcripts, ${s.hits.length} hits, ${voided} trials newly voided.`);
  return { scanned: true, files_scanned: s.files_scanned, hits: s.hits.length, voided };
}

// ---------- Metrics ----------
function bucket(r) {
  if (r.skipped) return 'skipped';
  if (r.voided) return 'voided';
  if (r.ok === false) return 'run_error'; // Harness failure, not a model failure. Reported and excluded.
  if (!(r.grade && r.grade.gradeable)) return 'ungraded';
  return 'counted';
}
const counted = (r) => bucket(r) === 'counted';
const bothOk = (r) => r.grade.category_ok === true && r.grade.priority_ok === true;
const trialPass = (r) => bothOk(r) && (!r.tone || r.tone.tone_pass === true);

function summarize(cellList, scope) {
  const inScope = (r) => scope === 'all' || r.trial <= TRIALS;
  const out = {};
  for (const cfg of CONFIGS) {
    const mine = cellList.filter((c) => c.config === cfg);
    const rows = mine.flatMap((c) => c.runs.filter(inScope));
    const cnt = rows.filter(counted);
    const judged = cnt.filter((r) => r.tone);
    const rate = (xs, f) => (xs.length ? round3(xs.filter(f).length / xs.length) : null);
    const perCell = mine.map((c) => c.runs.filter((r) => inScope(r) && counted(r))).filter((xs) => xs.length);
    const buckets = {};
    for (const r of rows) buckets[bucket(r)] = (buckets[bucket(r)] ?? 0) + 1;
    out[cfg] = {
      trials_planned: scope === 'main' ? mine.length * TRIALS : rows.length,
      trials_seen: rows.length,
      buckets,
      category_accuracy: rate(cnt, (r) => r.grade.category_ok === true),
      priority_accuracy: rate(cnt, (r) => r.grade.priority_ok === true),
      both_correct: rate(cnt, bothOk),
      tone_pass_rate: rate(judged, (r) => r.tone.tone_pass === true),
      tone_judged: judged.length,
      trial_pass_rate: rate(cnt, trialPass),
      cells_all_pass: rate(perCell, (xs) => xs.every(trialPass)),
      cells_split: perCell.filter((xs) => xs.some(trialPass) && !xs.every(trialPass)).length,
      sut_cost_usd: round2(rows.reduce((s, r) => s + (typeof r.sut_cost_usd === 'number' ? r.sut_cost_usd : 0), 0)),
    };
  }
  return out;
}

// ================= Run =================
phase('Gates');
if (!EST) {
  log('HALT: a full run needs args.est from the dry run.');
  return { round: ROUND, halted: 'missing-est', note: 'Run with {dryRun: true} first, then pass args.est.' };
}
ledger.reserved += TAIL_USD;
log(`${RR}${DRY ? ' DRY RUN' : ''}. Cap ${money(CAP_USD)}. Tail held back ${money(TAIL_USD)}.`);

let gate = null;
if (reserve(EST.gateUsd, 'launch gates')) {
  try {
    gate = await agent(
      [
        `Check the launch gates for SPE round ${ROUND}. Report facts only. Do not fix anything.`,
        `1. Run: git diff --quiet HEAD -- spe/predictions/${RR}.yaml spe/plans/${RR}.md ; echo $? ; git log -1 --format=%s -- spe/predictions/${RR}.yaml`,
        `   predictions_committed is true only if the diff exit code is 0 and the commit subject starts with "SPE ${RR} predict".`,
        '2. Grader selftest. Work in a new temp directory outside the repo. For every ticket in the answers file, build three run directories:',
        `   oracle (output.json label copied from ${ANSWERS}), empty (output.json is {}), and wrong (a category and a priority that both differ from the answer).`,
        `   Grade them with: python3 ${GRADER} --answers ${ANSWERS} --ticket <id> --runs <dir> --json`,
        '   Every oracle must pass both checks. Every empty and every wrong output must fail both checks.',
        `3. Control. Regrade ${PREV_RUN_DIR} with the current grader. Compare per-config category and priority accuracy with the measured ${PREV} numbers in spe/prediction-log.md.`,
        '   control_matches is true only if every number matches to 3 decimals. Put any mismatch in detail.',
      ].join('\n'),
      { label: `${RR} gates`, phase: 'Gates', schema: GATE_SCHEMA, model: MODEL },
    );
  } catch (e) {
    log(`Gate agent failed: ${e}`);
  }
  settle(EST.gateUsd, EST.gateUsd);
}
const gatesOk =
  gate && gate.predictions_committed && gate.selftest_oracle_pass && gate.selftest_empty_fails && gate.selftest_wrong_fails && gate.control_matches;
if (!gatesOk) {
  log(`HALT: a launch gate failed. ${gate?.detail ?? 'No gate result.'}`);
  return { round: ROUND, halted: 'gate-failed', gate, ledger: { spent: round2(ledger.spent), skips: ledger.skips } };
}
log('Gates passed: prediction frozen, grader selftest clean, control regrade matches.');

phase('Trials');
// Interleave configs per ticket so a budget cutoff hits both configs evenly.
const cells = (DRY ? DRY_CELLS : TICKETS.flatMap((t) => CONFIGS.map((c) => ({ config: c, ticket: t })))).map((c, idx) => ({ ...c, idx }));
log(`${cells.length} cells x ${TRIALS} trials = ${cells.length * TRIALS} planned trials.`);
const done = await pipeline(
  cells,
  (c) => runCell(c, MAIN_TRIALS, 'Trials'),
  (c) => gradeCell(c, 'Trials'),
  (c) => judgeCell(c, 'Trials'),
);
const byKey = new Map(done.map((c) => [key(c), c]));
log(`Trials done. Spent ${money(ledger.spent)} of ${money(CAP_USD)}.`);

phase('Peek scan');
const scans = [await peekScan('Trials', byKey)];
if (answerLeak && !halt) {
  halt = 'answer-key-leak';
  log('HALT: a trial touched the answer key. Extra trials are skipped. Report before close-out.');
}

phase('Split cells');
let extraRun = { split: 0, extended: 0, notExtended: [] };
if (EXTRA_PER_SPLIT > 0 && !halt) {
  const splits = [...byKey.values()].filter((c) => {
    const xs = c.runs.filter(counted);
    return xs.length > 1 && xs.some(trialPass) && !xs.every(trialPass);
  });
  const maxCells = Math.floor(EXTRA_MAX / EXTRA_PER_SPLIT);
  const chosen = splits.slice(0, maxCells);
  const extraNums = Array.from({ length: EXTRA_PER_SPLIT }, (_, i) => TRIALS + 1 + i);
  extraRun = { split: splits.length, extended: chosen.length, notExtended: splits.slice(maxCells).map(key) };
  if (extraRun.notExtended.length) log(`Extra-trial cap reached. Not extended: ${extraRun.notExtended.join(', ')}.`);
  log(`${splits.length} split cells. Adding ${EXTRA_PER_SPLIT} trials to ${chosen.length} of them.`);
  const extraOut = await parallel(
    chosen.map((c) => async () => {
      let x = await runCell({ config: c.config, ticket: c.ticket, idx: c.idx }, extraNums, 'Split cells');
      x = await gradeCell(x, 'Split cells');
      return judgeCell(x, 'Split cells');
    }),
  );
  for (const x of extraOut) byKey.get(key(x)).runs.push(...x.runs);
  scans.push(await peekScan('Split cells', byKey));
  if (answerLeak && !halt) halt = 'answer-key-leak';
} else {
  log(DRY ? 'Dry run: no extra trials.' : `No extra trials. Halt state: ${halt ?? 'none'}.`);
}

const finalCells = [...byKey.values()];
const primary = summarize(finalCells, 'main'); // Trials 1 to 5 only. Compare these with the prediction.
const withExtras = summarize(finalCells, 'all');
const ceiling = CONFIGS.every((cfg) => primary[cfg].both_correct === 1 && primary[cfg].tone_pass_rate === 1);
if (ceiling) log('Every config passed every check. The next round needs harder tickets or stricter graders.');

phase('Failure analysis');
const failing = finalCells
  .flatMap((c) =>
    c.runs.filter(counted).filter((r) => !trialPass(r)).map((r) => ({
      config: c.config,
      ticket: c.ticket,
      trial: r.trial,
      failed: [
        r.grade.category_ok ? null : 'category',
        r.grade.priority_ok ? null : 'priority',
        r.tone && !r.tone.tone_pass ? 'tone' : null,
      ].filter(Boolean),
      got: { category: r.category, priority: r.priority },
      expected: { category: r.grade.expected_category, priority: r.grade.expected_priority },
      tone_reason: r.tone?.reason ?? null,
      transcript: `${RUN_DIR}/${c.config}/${c.ticket}/t${r.trial}/transcript.jsonl`,
    })),
  )
  .slice(0, 80);
let analysis = null;
if (failing.length && useTail(EST.analysisUsd, 'failure analysis')) {
  try {
    analysis = await agent(
      [
        `Group the failed trials of SPE round ${ROUND} into failure types. Do not edit any file.`,
        'Read spe/failures.md. When a failure matches an existing type, put its F-number in existing_f. Otherwise set existing_f to null.',
        'Open the transcripts listed below to find where each trial went wrong. Name the type by its cause, not its symptom.',
        'For each type give name, kind, what, how_to_spot, seen_in (config/ticket/tN), count, and fix.',
        'If a failure looks like a grader or judge bug, say so in kind. That is a failure type too.',
        JSON.stringify(failing),
      ].join('\n\n'),
      { label: `${RR} failure analysis`, phase: 'Failure analysis', schema: FA_SCHEMA, model: MODEL },
    );
  } catch (e) {
    log(`Failure analysis failed: ${e}`);
  }
}

phase('Completeness critic');
const coverageGaps = [];
for (const cfg of CONFIGS) {
  const p = primary[cfg];
  const seen = Object.values(p.buckets).reduce((s, n) => s + n, 0);
  if (seen !== p.trials_planned) coverageGaps.push(`${cfg}: ${seen} trials seen but ${p.trials_planned} planned.`);
  if ((p.buckets.counted ?? 0) !== p.tone_judged) coverageGaps.push(`${cfg}: ${p.buckets.counted ?? 0} graded trials but ${p.tone_judged} tone scores.`);
}
let critic = null;
if (useTail(EST.criticUsd, 'completeness critic')) {
  try {
    critic = await agent(
      [
        `You are the completeness critic for SPE round ${ROUND}${DRY ? ' (dry run)' : ''}. Do not read any file. Judge only the data below.`,
        `The approved plan requires: configs ${CONFIGS.join(' and ')}, ${DRY ? DRY_CELLS.length + ' dry-run cells' : TICKETS.length + ' tickets'}, ${TRIALS} trials per cell, the code grader on label.category and label.priority, an Opus tone judge, a spend cap of ${money(CAP_USD)}, a peek scan, and failure analysis.`,
        'List every gap that would make the measured numbers unfit to compare with the prediction. Examples are missing cells, uneven skips between configs, unscanned trials, ungraded trials, missing tone scores, or a halt.',
        `Code-found gaps: ${JSON.stringify(coverageGaps)}`,
        `Primary metrics: ${JSON.stringify(primary)}`,
        `Scans: ${JSON.stringify(scans)}. Halt: ${halt ?? 'none'}. Skips: ${ledger.skips.length}. Spent: ${money(ledger.spent)}.`,
        `Failure types found: ${analysis ? analysis.types.length : 'analysis not run'}.`,
      ].join('\n\n'),
      { label: `${RR} completeness critic`, phase: 'Completeness critic', schema: CRITIC_SCHEMA, model: MODEL },
    );
  } catch (e) {
    log(`Critic failed: ${e}`);
  }
}

ledger.reserved -= tail.left;
const capHit = ledger.skips.some((s) => s.reason === 'cap');
const allTrials = finalCells.flatMap((c) => c.runs.filter((r) => typeof r.sut_cost_usd === 'number'));
log(`Done. Spent ${money(ledger.spent)} of ${money(CAP_USD)}. Halt: ${halt ?? 'none'}. Cap hit: ${capHit}.`);

return {
  round: ROUND,
  dryRun: DRY,
  halted: halt ?? (capHit ? 'budget-cap' : null),
  gate,
  metrics_primary_trials_1_to_5: primary,
  metrics_with_extra_trials: withExtras,
  ceiling,
  split_cells: extraRun,
  scans,
  answer_leak: answerLeak,
  voided: finalCells.flatMap((c) => c.runs.filter((r) => r.voided).map((r) => ({ cell: key(c), trial: r.trial, why: r.voided }))),
  failure_types: analysis?.types ?? null,
  critic,
  coverage_gaps: coverageGaps,
  ledger: { cap: CAP_USD, spent_usd: round2(ledger.spent), skips: ledger.skips, note: 'Spend counts runner-reported API cost plus agent costs estimated from args.est.' },
  dry_cost: DRY
    ? {
        trials_with_cost: allTrials.length,
        mean_sut_cost_per_trial_usd: allTrials.length ? round3(allTrials.reduce((s, r) => s + r.sut_cost_usd, 0) / allTrials.length) : null,
        note: 'Read the agent cost from the run usage report. Set args.est for the full run from these numbers.',
      }
    : null,
  trials: finalCells.flatMap((c) =>
    c.runs.map((r) => ({
      config: c.config,
      ticket: c.ticket,
      trial: r.trial,
      bucket: bucket(r),
      category_ok: r.grade?.category_ok ?? null,
      priority_ok: r.grade?.priority_ok ?? null,
      tone_pass: r.tone?.tone_pass ?? null,
      tool_calls: r.tool_calls ?? null,
      sut_cost_usd: r.sut_cost_usd ?? null,
    })),
  ),
};
